from binascii import unhexlify

def analyze_bytes(data, n=3):
    """Analyze byte frequencies and patterns"""
    freqs = {}
    for b in data:
        if b in freqs:
            freqs[b] += 1
        else:
            freqs[b] = 1

    sorted_freqs = sorted(freqs.items(), key=lambda x: x[1], reverse=True)
    print("\nByte frequencies:")
    for byte, count in sorted_freqs[:10]:
        print(f"0x{byte:02x}: {count} times")

    # Look for repeating sequences
    for length in range(2, 5):
        sequences = {}
        for i in range(len(data) - length + 1):
            seq = data[i:i+length]
            if seq in sequences:
                sequences[seq] += 1
            else:
                sequences[seq] = 1

        repeated = {k: v for k, v in sequences.items() if v > 1}
        if repeated:
            print(f"\nRepeating sequences of length {length}:")
            for seq, count in sorted(repeated.items(), key=lambda x: x[1], reverse=True)[:5]:
                print(f"{seq.hex()}: {count} times")

def try_decrypt_n3(ciphertext, key):
    """Try to decrypt with given key assuming n=3"""
    plaintext = bytearray()
    for i, c in enumerate(ciphertext):
        k = key[i % len(key)]
        p = (c - k) & 0x7
        plaintext.append(p)
    return plaintext

